function initCaseStudySwiper(e){if("undefined"==typeof Swiper)return;const t=e.closest(".case-study-section");new Swiper(e,{slidesPerView:"auto",spaceBetween:24,speed:500,grabCursor:!0,keyboard:{enabled:!0},navigation:t?{nextEl:t.querySelector(".case-study-section__nav--next"),prevEl:t.querySelector(".case-study-section__nav--prev")}:void 0,breakpoints:{0:{spaceBetween:12},577:{spaceBetween:24}}})}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".case-study-section__swiper").forEach(initCaseStudySwiper)});